import sys,json
sys.path.insert(0,sys.argv[1])
import click
from click.testing import CliRunner
@click.command()
@click.option("-o","--opt",is_flag=False,flag_value="flag",default="default",type=str)
@click.option("--other",is_flag=True)
def cli(opt,other):return opt,other
values=[]
for args in [["--opt=--other"],["-o--other"]]:
 r=CliRunner().invoke(cli,args,standalone_mode=False)
 values.append({"args":args,"return_value":r.return_value,"exception_type":type(r.exception).__name__ if r.exception else None})
print(json.dumps(values))
